{
  "summary": "You may be eligible for the FT(PMC) scheme, but it depends on the date you sold the previous flat and other criteria; see the official HDB guidelines.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "FT(PMC) (First‑Timer – Previously Married Couple) is a BTO category for couples where at least one spouse previously owned an HDB flat but sold it before 1 January 2019 and the couple now meets all other first‑timer criteria."
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "If the previous flat was sold after 1 January 2019, the couple is generally not eligible for FT(PMC) and must apply under the regular First‑Timer (FT) category."
    },
    {
      "claim_id": "c3",
      "kind": "preparation_step",
      "text": "Check the HFE (Housing Flat Eligibility) letter or HDB portal to confirm the exact sale date of Darren's previous flat and whether it meets the pre‑2019 requirement for FT(PMC)."
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "Gather supporting documents such as the sale deed of the previous flat, HFE letter, NRICs, and marriage certificate to be ready for the BTO application."
    },
    {
      "claim_id": "c5",
      "kind": "caveat",
      "text": "Eligibility rules can change; verify the latest FT(PMC) criteria on the HDB website (hdb.gov.sg) or the HDB Flat Portal before applying."
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}
